// A mini broker: the VM gets a capability, the broker keeps the key and checks every request.
import { createHash, randomBytes } from "node:crypto";
import { createServer } from "node:http";

const GITHUB_TOKEN = "ghs_THE_REAL_KEY_lives_only_here"; // stands for the one-hour GitHub App token
const runs = new Map(); // sha256(capability) -> the run's scope; the capability itself is never stored
const sha256 = (s) => createHash("sha256").update(s).digest("hex");

const openRun = (scope) => {
  const capability = randomBytes(32).toString("hex");
  runs.set(sha256(capability), scope);
  return capability;
};
const scopeFor = (authorization) => {
  if (!authorization?.startsWith("Bearer ")) return null;
  const scope = runs.get(sha256(authorization.slice("Bearer ".length)));
  return scope && Date.parse(scope.expiresAt) > Date.now() ? scope : null;
};
const reply = (res, status, text) => { res.writeHead(status); res.end(text); };

createServer((req, res) => {
  const url = new URL(req.url, "http://broker");
  if (url.pathname === "/health") return reply(res, 200, "ok");
  const scope = scopeFor(req.headers.authorization);
  if (!scope) return reply(res, 401, "missing or unknown capability");
  if (url.pathname === "/v1/scope") return reply(res, 200, JSON.stringify(scope));
  if (url.pathname === "/v1/push") {
    const repo = url.searchParams.get("repo"), branch = url.searchParams.get("branch");
    if (repo !== scope.repo || branch !== scope.branch) {
      console.log(`audit: REFUSED ${scope.runId} push ${repo} ${branch}`);
      return reply(res, 403, `refused: this run may push only ${scope.branch} in ${scope.repo}`);
    }
    console.log(`audit: allowed ${scope.runId} push ${repo} ${branch} (token ${GITHUB_TOKEN.slice(0, 4)}… added here)`);
    return reply(res, 200, `pushed ${branch}; the token never left the broker`);
  }
  reply(res, 404, "no such route");
}).listen(process.env.BROKER_PORT ?? 8080);

