#!/usr/bin/env node
// The broker's git check. A push first lists the refs it wants to change, one line each: old-sha new-sha ref.
const BRANCH = "nova/RH-1234";
const ZERO = "0".repeat(40);
let input = "";
process.stdin.on("data", (c) => (input += c)).on("end", () => {
  for (const line of input.trim().split("\n")) {
    const [oldSha, newSha, ref] = line.split(" ");
    const why = ref !== `refs/heads/${BRANCH}` ? `only ${BRANCH} can be pushed from this run, not ${ref}`
      : newSha === ZERO ? "deleting the branch is not allowed" : null;
    if (why) {
      console.error(`broker: refused: ${why}`);
      process.exit(1);
    }
    console.error(`broker: ok ${ref} ${oldSha.slice(0, 7)}..${newSha.slice(0, 7)}`);
  }
});
EOF
